using GestaoClientes.Application; using GestaoClientes.Domain; using GestaoClientes.Infrastructure; using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddDbContext<GestaoClientesDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("SqlServer"))); builder.Services.AddScoped<IClienteRepository,ClienteRepository>(); builder.Services.AddScoped<ClienteService>(); var app=builder.Build(); app.UseMiddleware<ErroMiddleware>(); app.UseSwagger(); app.UseSwaggerUI(); using(var scope=app.Services.CreateScope()) await Seeder.SemearAsync(scope.ServiceProvider.GetRequiredService<GestaoClientesDbContext>()); app.UseHttpsRedirection(); app.MapControllers(); app.Run();
public sealed class ErroMiddleware(RequestDelegate next){public async Task Invoke(HttpContext c){try{await next(c);}catch(Exception e) when(e is DomainException or ArgumentException){await Responder(c,422,e.Message);}catch(InvalidOperationException e){await Responder(c,409,e.Message);}catch(KeyNotFoundException e){await Responder(c,404,e.Message);}}static async Task Responder(HttpContext c,int status,string msg){c.Response.StatusCode=status;await c.Response.WriteAsJsonAsync(new{erro=msg});}}
